using SixLabors.ImageSharp.Formats.Av1;
using SixLabors.ImageSharp.Formats.Av1.Bitstream;

namespace SixLabors.ImageSharp.Codecs.Av1.Tests;

/// <summary>
/// Validates per-block deblocking filter levels on a real eight-frame non-error-resilient AV1/IVF clip
/// (generated by aomenc): the later frames carry non-zero loop-filter levels, so each block's level is
/// derived from the frame level and the block's reference/mode deltas rather than applied frame-wide,
/// on top of the primary-reference CDF inheritance chain. Every decoded frame's luma and chroma must be
/// exactly equal to dav1d's decoded output.
/// </summary>
public class Av1PerBlockLoopFilterDecodeTests
{
    private const string ClipIvfBase64 =
        "";

    private static readonly string[] Dav1dLumaBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    ];

    private static readonly string[] Dav1dUBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    ];

    private static readonly string[] Dav1dVBase64 = [
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    ];

    [Fact]
    public void DecodeAllFrames_PerBlockFilterLevels_MatchDav1dExactly()
    {
        using MemoryStream stream = new(Convert.FromBase64String(ClipIvfBase64));
        List<Av1TileDecoder> frames = Av1DecoderCore.DecodeAllFrames(stream);

        Assert.Equal(8, frames.Count);
        for (int i = 0; i < frames.Count; i++)
        {
            Assert.Equal(Av1TestData.Widen(Convert.FromBase64String(Dav1dLumaBase64[i])), frames[i].Luma.Samples);
            Assert.Equal(Av1TestData.Widen(Convert.FromBase64String(Dav1dUBase64[i])), frames[i].ChromaU.Samples);
            Assert.Equal(Av1TestData.Widen(Convert.FromBase64String(Dav1dVBase64[i])), frames[i].ChromaV.Samples);
        }
    }
}
